sys_script_include.script:
var EventScheduleUtils = Class.create();
EventScheduleUtils.prototype = {
    initialize: function() {},

    getScheduleDetails: function(eventId) {
        if (!eventId) {
            return { error: "Event ID is required." };
        }

        var scheduleGR = new GlideRecord('x_1610434_event_0_schedule'); 
        scheduleGR.addQuery('event_id', eventId);
        scheduleGR.query();

        if (scheduleGR.next()) {
            return {
                event_id: scheduleGR.getValue('event_id'),
                schedule_date: scheduleGR.getValue('schedule_date'),
                start_time: scheduleGR.getValue('start_time'),
                end_time: scheduleGR.getValue('end_time'),
                description: scheduleGR.getValue('description')
            };
        }

        return { error: "No schedule found for the specified event." };
    },

    type: 'EventScheduleUtils'
};
